import React from "react";
import { Box } from "@mui/material";

const CustomBox = ({ children, sx }) => (
  <Box
    sx={{
      backgroundColor: "#ffffff",
      borderRadius: "16px",
      boxShadow: "0px 4px 20px rgba(0, 0, 0, 0.05)",
      p: 3,
      mb: 3,
      ...sx,
    }}
  >
    {children}
  </Box>
);

export default CustomBox;
